package com.bananalab.lite;
import android.content.*;import android.net.Uri;import android.security.keystore.*;import android.util.Base64;import java.io.*;import java.security.*;import java.security.cert.*;import java.security.spec.*;import javax.crypto.*;import javax.crypto.spec.*;import java.util.*;import java.util.zip.*;import dalvik.system.DexClassLoader;import org.json.*;
/** Signing authority is imported by the owner; no private signing key is shipped in the APK. */
final class ApkSigning{
 static final String ALIAS="banana-owner-signing-wrap";
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-apk-owner",0);}
 static String b64(byte[] b){return Base64.encodeToString(b,Base64.NO_WRAP);}static byte[] un64(String s){return Base64.decode(s,Base64.DEFAULT);}
 static javax.crypto.SecretKey wrapping()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias(ALIAS))return (javax.crypto.SecretKey)store.getKey(ALIAS,null);KeyGenerator generator=KeyGenerator.getInstance("AES","AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return generator.generateKey();}
 static java.security.cert.X509Certificate certificate(byte[] data)throws Exception{return (java.security.cert.X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(data));}
 static void sameOwner(Context c,X509Certificate cert)throws Exception{android.content.pm.PackageInfo info=c.getPackageManager().getPackageInfo(c.getPackageName(),android.content.pm.PackageManager.GET_SIGNATURES);boolean found=false;for(android.content.pm.Signature signature:info.signatures)if(MessageDigest.isEqual(signature.toByteArray(),cert.getEncoded()))found=true;if(!found)throw new GeneralSecurityException("La firma importada no corresponde a esta Banana instalada.");}
 static String importKey(Context c,InputStream stream)throws Exception{byte[] key=null,cert=null;try(ZipInputStream zip=new ZipInputStream(stream)){ZipEntry entry;int count=0;while((entry=zip.getNextEntry())!=null){if(++count>12)throw new IOException("Paquete de firma inválido.");if(entry.getName().equals("private-key.pk8"))key=OnDeviceJava.bytes(zip,16000);else if(entry.getName().equals("certificate.der"))cert=OnDeviceJava.bytes(zip,16000);else if(!entry.isDirectory())OnDeviceJava.bytes(zip,16000);}}if(key==null||cert==null)throw new IOException("Elegí Banana-Firma-privada.zip, no el ZIP de fuentes.");X509Certificate certificate=certificate(cert);sameOwner(c,certificate);PrivateKey privateKey=KeyFactory.getInstance(certificate.getPublicKey().getAlgorithm()).generatePrivate(new PKCS8EncodedKeySpec(key));String algorithm=certificate.getPublicKey().getAlgorithm().equals("RSA")?"SHA256withRSA":"SHA256withECDSA";Signature challenge=Signature.getInstance(algorithm);challenge.initSign(privateKey);challenge.update(new byte[]{66,97,110,97,110,97});byte[] signed=challenge.sign();challenge.initVerify(certificate);challenge.update(new byte[]{66,97,110,97,110,97});if(!challenge.verify(signed))throw new GeneralSecurityException("La clave y el certificado no coinciden.");JSONObject raw=new JSONObject().put("key",b64(key)).put("cert",b64(cert));Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,wrapping());String encrypted=new JSONObject().put("iv",b64(cipher.getIV())).put("sealed",b64(cipher.doFinal(raw.toString().getBytes("UTF-8")))).toString();if(!prefs(c).edit().putString("sealed",encrypted).commit())throw new IOException("No pude guardar la firma protegida.");Arrays.fill(key,(byte)0);return "Firma del propietario importada y protegida en este dispositivo. No se incorpora a las APK generadas.";}
 static Object[] owner(Context c)throws Exception{String raw=prefs(c).getString("sealed","");if(raw.isEmpty())throw new IOException("Configurá una vez tu clave de actualización: importa firma privada. Es un archivo privado, no otra APK.");JSONObject sealed=new JSONObject(raw);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,wrapping(),new GCMParameterSpec(128,un64(sealed.getString("iv"))));JSONObject clear=new JSONObject(new String(cipher.doFinal(un64(sealed.getString("sealed"))),"UTF-8"));X509Certificate cert=certificate(un64(clear.getString("cert")));sameOwner(c,cert);PrivateKey key=KeyFactory.getInstance(cert.getPublicKey().getAlgorithm()).generatePrivate(new PKCS8EncodedKeySpec(un64(clear.getString("key"))));return new Object[]{key,cert};}
 static ClassLoader loader(Context c)throws Exception{JSONObject provenance=new JSONObject(AppJavaChat.asset(c,"java-tools/apksig-provenance.json",4000));String expected=provenance.getString("sha256");if(!expected.matches("[a-f0-9]{64}"))throw new IOException("Identidad de herramienta inválida.");File file=new File(OnDeviceJava.home(c),"apksig-"+expected.substring(0,16)+".jar");if(!file.exists())try(InputStream in=c.getAssets().open("java-tools/apksig.jar")){OnDeviceJava.immutable(file,OnDeviceJava.bytes(in,5000000));}if(!ProjectRuntime.digest(file).equals(provenance.getString("sha256")))throw new IOException("La herramienta de firma no coincide con la versión instalada.");File opt=new File(OnDeviceJava.home(c),"sign-opt");opt.mkdirs();return new DexClassLoader(file.getAbsolutePath(),opt.getAbsolutePath(),null,c.getClassLoader());}
 static void sign(Context c,File input,File output)throws Exception{Object[] owner=owner(c);ClassLoader loader=loader(c);Class<?> config=loader.loadClass("com.android.apksig.ApkSigner$SignerConfig$Builder");Object configBuilder=config.getConstructor(String.class,PrivateKey.class,List.class).newInstance("BananaOwner",owner[0],Arrays.asList(owner[1]));Object signerConfig=config.getMethod("build").invoke(configBuilder);Class<?> builder=loader.loadClass("com.android.apksig.ApkSigner$Builder");Object b=builder.getConstructor(List.class).newInstance(Arrays.asList(signerConfig));for(String method:new String[]{"setV1SigningEnabled","setV2SigningEnabled","setV3SigningEnabled"})builder.getMethod(method,boolean.class).invoke(b,true);builder.getMethod("setV4SigningEnabled",boolean.class).invoke(b,false);builder.getMethod("setMinSdkVersion",int.class).invoke(b,23);builder.getMethod("setInputApk",File.class).invoke(b,input);builder.getMethod("setOutputApk",File.class).invoke(b,output);Object signer=builder.getMethod("build").invoke(b);signer.getClass().getMethod("sign").invoke(signer);verify(c,output);}
 static void verify(Context c,File file)throws Exception{ClassLoader loader=loader(c);Class<?> builder=loader.loadClass("com.android.apksig.ApkVerifier$Builder");Object b=builder.getConstructor(File.class).newInstance(file);builder.getMethod("setMinCheckedPlatformVersion",int.class).invoke(b,23);Object verifier=builder.getMethod("build").invoke(b);Object result=verifier.getClass().getMethod("verify").invoke(verifier);if(!(Boolean)result.getClass().getMethod("isVerified").invoke(result))throw new GeneralSecurityException("La APK reconstruida no pasó la verificación de firma: "+result.getClass().getMethod("getErrors").invoke(result));List<?> certificates=(List<?>)result.getClass().getMethod("getSignerCertificates").invoke(result);if(certificates.size()!=1)throw new GeneralSecurityException("Identidad de firma inesperada.");sameOwner(c,(X509Certificate)certificates.get(0));}
}
